#!/usr/bin/env bash
# Rebuild shiki.mjs, the self-contained highlighter that highlight.ts imports.
# Edit package.json (version) or entry.ts (languages, themes), then run this.
set -euo pipefail
cd "$(dirname "$0")"
if [[ -f bun.lock ]]; then bun install --frozen-lockfile; else bun install; fi
version=$(jq -r '.dependencies["@shikijs/core"]' package.json)
bun build entry.ts --target=node --format=esm --minify \
  --banner "// Generated by build.sh from shiki $version (MIT). Do not edit." \
  --outfile shiki.mjs
rm -rf node_modules
